import RNA
target="(((((((((((((((.(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).)))))))))))))))"
n=len(target)

# initial candidate: alternating stems, GAAAC loops
def build():
    seq=['A']*n
    # pairs
    stack=[]; pairs=set()
    for i,c in enumerate(target):
        if c=='(': stack.append(i)
        elif c==')':
            j=stack.pop(); pairs.add((j,i))
    allp=sorted([p for p in pairs if p[0]<p[1]])
    for idx,(i,j) in enumerate(allp):
        # alternate GC/CG, but make inner pairs AU to reduce alt strength
        # stem idx within a stem: alternate
        if idx%3==0:
            seq[i]='G'; seq[j]='C'
        elif idx%3==1:
            seq[i]='C'; seq[j]='G'
        else:
            seq[i]='A'; seq[j]='U'
    # loops GAAAC
    hairpins=[(i,j) for (i,j) in allp if all((k not in [pp for pp in range(i+1,j)] or True) for k in range(i+1,j))]
    # simpler: loop positions are unpaired '.'
    for i in range(n):
        if target[i]=='.':
            seq[i]='A'
    # set known tetraloop-like: for each hairpin loop len 5, set GAAAC
    paired=[None]*n
    for (i,j) in pairs: paired[i]=j; paired[j]=i
    for (i,j) in allp:
        if all(paired[k] is None for k in range(i+1,j)):
            lp=j-i-1
            if lp==5:
                for k,b in zip(range(i+1,j),"GAAAC"):
                    seq[k]=b
            # closing GC
            seq[i]='G'; seq[j]='C'
    return ''.join(seq)

